// static
bool StructTraits<::skills::mojom::InitialDialogState::DataView, ::skills::mojom::InitialDialogStatePtr>::Read(
    ::skills::mojom::InitialDialogState::DataView input,
    ::skills::mojom::InitialDialogStatePtr* output) {
  bool success = true;
  ::skills::mojom::InitialDialogStatePtr result(::skills::mojom::InitialDialogState::New());
  
      if (success && !input.ReadDialogType(&result->dialog_type))
        success = false;
      if (success && !input.ReadSkill(&result->skill))
        success = false;
  *output = std::move(result);
  return success;
}


